package com.cinebook.payment;
import com.cinebook.auth.*;import com.cinebook.booking.*;import com.cinebook.common.ApiException;import com.cinebook.events.OutboxService;import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.beans.factory.annotation.Value;import org.springframework.core.env.Environment;import org.springframework.http.HttpStatusCode;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.client.RestClient;import org.springframework.web.client.RestClientResponseException;import java.math.BigDecimal;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Instant;import java.util.*;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;
@Service
public class RazorpayPaymentService {
 private final UserRepository users;private final BookingRepository bookingRepository;private final SeatHoldRepository holds;private final ShowSeatRepository inventory;private final PaymentRepository payments;private final RefundRepository refunds;private final PaymentWebhookEventRepository webhookEvents;private final BookingService bookings;private final CouponService coupons;private final ObjectMapper mapper;private final RestClient.Builder restBuilder;private final String mode,keyId,keySecret,webhookSecret;private final boolean simulatorEnabled;
 public RazorpayPaymentService(UserRepository users,BookingRepository bookingRepository,SeatHoldRepository holds,ShowSeatRepository inventory,PaymentRepository payments,RefundRepository refunds,PaymentWebhookEventRepository webhookEvents,BookingService bookings,CouponService coupons,ObjectMapper mapper,RestClient.Builder restBuilder,@Value("${app.payments.mode:SIMULATOR}") String mode,@Value("${app.payments.razorpay-key-id:}") String keyId,@Value("${app.payments.razorpay-key-secret:}") String keySecret,@Value("${app.payments.razorpay-webhook-secret:}") String webhookSecret,@Value("${app.payments.simulator-enabled:true}") boolean simulatorEnabled,Environment environment){this.users=users;this.bookingRepository=bookingRepository;this.holds=holds;this.inventory=inventory;this.payments=payments;this.refunds=refunds;this.webhookEvents=webhookEvents;this.bookings=bookings;this.coupons=coupons;this.mapper=mapper;this.restBuilder=restBuilder;this.mode=mode;this.keyId=keyId;this.keySecret=keySecret;this.webhookSecret=webhookSecret;this.simulatorEnabled=simulatorEnabled&&!Arrays.asList(environment.getActiveProfiles()).contains("prod");}
 public RazorpayDtos.OptionsView options(){boolean gateway=razorpayEnabled();boolean simulator=simulatorEnabled&&!gateway;String selected=gateway?"RAZORPAY":simulator?"SIMULATOR":"UNAVAILABLE";return new RazorpayDtos.OptionsView(selected,gateway,gateway?keyId:null,simulator);}
 @Transactional public RazorpayDtos.OrderView createOrder(String email,String holdToken,String idempotencyKey,String couponCode,String correlationId){
  if(!razorpayEnabled())throw new ApiException(503,"RAZORPAY_NOT_CONFIGURED","Razorpay is not configured. Set PAYMENT_MODE=RAZORPAY and valid server-side test credentials before accepting payments.");
  if(idempotencyKey==null||idempotencyKey.isBlank())throw new ApiException(400,"IDEMPOTENCY_KEY_REQUIRED","Idempotency-Key is required to create a Razorpay order");if(idempotencyKey.length()>120)throw new ApiException(400,"INVALID_IDEMPOTENCY_KEY","Idempotency-Key must be at most 120 characters");UserAccount user=users.findByEmailIgnoreCaseForUpdate(email).orElseThrow(()->new ApiException(404,"USER_NOT_FOUND","User was not found"));SeatHold hold=holds.findByToken(holdToken).orElseThrow(()->new ApiException(404,"HOLD_NOT_FOUND","Seat hold was not found"));if(!hold.getUser().getId().equals(user.getId()))throw new ApiException(403,"HOLD_NOT_OWNED","This hold belongs to another account");
  Optional<PaymentRecord> previous=payments.findByIdempotencyKey(idempotencyKey);if(previous.isPresent()){PaymentRecord p=previous.get();if(p.getProvider()!=PaymentRecord.Provider.RAZORPAY||!p.getHold().getId().equals(hold.getId()))throw new ApiException(409,"IDEMPOTENCY_KEY_REUSED","This idempotency key belongs to another payment");if(p.getProviderReference()!=null)return orderView(p,"REUSED","Existing Razorpay order returned for this idempotency key");return new RazorpayDtos.OrderView("RAZORPAY",keyId,null,p.getAmount().movePointRight(2).longValue(),p.getCurrency(),p.getId().toString(),"PENDING_RECONCILIATION","This order request has an ambiguous result. Do not submit another order; reconcile it in the Razorpay test dashboard.");}
  if(payments.existsByHoldIdAndStatus(hold.getId(),PaymentRecord.Status.PENDING))throw new ApiException(409,"PAYMENT_IN_PROGRESS","A payment attempt is already pending for this hold");if(!hold.isActiveNow())throw new ApiException(409,"HOLD_EXPIRED","Your seat hold has expired. Please select seats again");List<ShowSeat> heldSeats=inventory.findAllByHoldId(hold.getId());if(heldSeats.isEmpty()||heldSeats.stream().anyMatch(s->s.getStatus()!=InventoryStatus.HELD||s.getHold()==null||!s.getHold().getId().equals(hold.getId())||s.getHoldExpiresAt()==null||!s.getHoldExpiresAt().isAfter(Instant.now())))throw new ApiException(409,"HOLD_EXPIRED","Seat hold is no longer valid");BigDecimal subtotal=heldSeats.stream().map(ShowSeat::getPrice).reduce(BigDecimal.ZERO,BigDecimal::add);CouponService.PriceQuote quote=coupons.calculate(subtotal,couponCode);long amountPaise=quote.total().movePointRight(2).longValueExact();PaymentRecord payment=payments.saveAndFlush(new PaymentRecord(hold,PaymentRecord.Provider.RAZORPAY,quote.total(),idempotencyKey));payment.setCouponCode(quote.couponCode());
  try{Map<String,Object> payload=new LinkedHashMap<>();payload.put("amount",amountPaise);payload.put("currency","INR");payload.put("receipt",shortReceipt(idempotencyKey));payload.put("notes",Map.of("hold_token",hold.getToken(),"cinebook_payment_id",payment.getId().toString()));JsonNode response=client().post().uri("/v1/orders").body(payload).retrieve().body(JsonNode.class);if(response==null||!response.hasNonNull("id")){return new RazorpayDtos.OrderView("RAZORPAY",keyId,null,amountPaise,"INR",payment.getId().toString(),"PENDING_RECONCILIATION","The gateway did not return a usable order ID. Do not retry with a new key; reconcile the pending record.");}String orderId=response.path("id").asText();long gatewayAmount=response.path("amount").asLong(-1);if(gatewayAmount!=amountPaise||!"INR".equalsIgnoreCase(response.path("currency").asText(""))){payment.setStatus(PaymentRecord.Status.FAILED);return new RazorpayDtos.OrderView("RAZORPAY",keyId,orderId,amountPaise,"INR",payment.getId().toString(),"FAILED","The gateway order amount did not match the server quote; the order was not made payable by this application.");}payment.setProviderReference(orderId);return orderView(payment,"CREATED","Razorpay test order created. Verify the checkout signature on the backend after payment.");}
  catch(RestClientResponseException ex){if(ex.getStatusCode().is4xxClientError()){payment.setStatus(PaymentRecord.Status.FAILED);return new RazorpayDtos.OrderView("RAZORPAY",keyId,null,amountPaise,"INR",payment.getId().toString(),"FAILED","Razorpay rejected the order request. Check test credentials and gateway response logs.");}return new RazorpayDtos.OrderView("RAZORPAY",keyId,null,amountPaise,"INR",payment.getId().toString(),"PENDING_RECONCILIATION","Gateway outcome is ambiguous. Do not retry with another key; reconcile the pending payment/order in Razorpay test mode.");}
  catch(Exception ex){return new RazorpayDtos.OrderView("RAZORPAY",keyId,null,amountPaise,"INR",payment.getId().toString(),"PENDING_RECONCILIATION","Gateway outcome is ambiguous. Do not retry with another key; reconcile the pending payment/order in Razorpay test mode.");}
 }
 @Transactional public BookingDtos.PaymentView verify(String email,String orderId,String paymentId,String signature,String correlationId){if(!razorpayEnabled())throw new ApiException(503,"RAZORPAY_NOT_CONFIGURED","Razorpay test mode is not enabled");PaymentRecord p=payments.findByProviderReference(orderId).orElseThrow(()->new ApiException(404,"PAYMENT_ORDER_NOT_FOUND","No payment record matches this Razorpay order"));if(p.getProvider()!=PaymentRecord.Provider.RAZORPAY)throw new ApiException(409,"PAYMENT_PROVIDER_MISMATCH","This is not a Razorpay payment");UserAccount u=users.findByEmailIgnoreCase(email).orElseThrow(()->new ApiException(404,"USER_NOT_FOUND","User was not found"));if(!p.getHold().getUser().getId().equals(u.getId()))throw new ApiException(403,"PAYMENT_NOT_OWNED","This payment belongs to another account");if(p.getStatus()==PaymentRecord.Status.SUCCEEDED)return new BookingDtos.PaymentView(p.getId().toString(),p.getProvider().name(),p.getStatus().name(),p.getAmount(),p.getCurrency(),"Razorpay payment already verified",p.getBooking()==null?null:bookings.ticket(email,p.getBooking().getId()));if(!checkoutSignatureValid(orderId,paymentId,signature))throw new ApiException(400,"INVALID_PAYMENT_SIGNATURE","Razorpay payment signature could not be verified");BookingDtos.PaymentView result=bookings.confirmGatewayPayment(p.getId(),paymentId,correlationId);if("REFUND_PENDING".equals(result.status()))requestRefundForCapturedPayment(p.getId(),paymentId,correlationId);return result;}
 @Transactional public Map<String,Object> handleWebhook(String body,String signature,String eventId,String correlationId){if(webhookSecret==null||webhookSecret.isBlank())throw new ApiException(503,"WEBHOOK_NOT_CONFIGURED","Razorpay webhook secret is not configured");if(eventId==null||eventId.isBlank())throw new ApiException(400,"WEBHOOK_EVENT_ID_REQUIRED","X-Razorpay-Event-Id is required");if(!constantEquals(hmac(body,webhookSecret),signature))throw new ApiException(400,"INVALID_WEBHOOK_SIGNATURE","Razorpay webhook signature could not be verified");Optional<PaymentWebhookEvent> existing=webhookEvents.findByEventId(eventId);if(existing.isPresent())return Map.of("received",true,"duplicate",true,"eventId",eventId,"status",existing.get().getStatus());String eventType="unknown";try{JsonNode root=mapper.readTree(body);eventType=root.path("event").asText("unknown");String payloadHash=sha256(body);PaymentWebhookEvent event=webhookEvents.saveAndFlush(new PaymentWebhookEvent(eventId,eventType,payloadHash));JsonNode entity=eventEntity(root,eventType);if(eventType.startsWith("payment.")){String orderId=entity.path("order_id").asText("");String paymentId=entity.path("id").asText("");PaymentRecord payment=payments.findByProviderReference(orderId).orElse(null);if(payment==null){event.failed();return Map.of("received",true,"duplicate",false,"eventId",eventId,"status","UNMATCHED_PAYMENT");}if("payment.captured".equals(eventType)){BookingDtos.PaymentView result=bookings.confirmGatewayPayment(payment.getId(),paymentId,correlationId);if("REFUND_PENDING".equals(result.status()))requestRefundForCapturedPayment(payment.getId(),paymentId,correlationId);}else if("payment.failed".equals(eventType)){bookings.markGatewayPaymentFailed(payment.getId(),eventId);}event.processed();}else if(eventType.startsWith("refund.")){String refundId=entity.path("id").asText("");RefundRecord refund=refunds.findByProviderReference(refundId).orElse(null);if(refund==null){event.ignored();}else if("refund.processed".equals(eventType)){bookings.finalizeGatewayRefund(refund.getId());event.processed();}else if("refund.failed".equals(eventType)){refund.setStatus("FAILED");event.processed();}else{event.ignored();}}else{event.ignored();}return Map.of("received",true,"duplicate",false,"eventId",eventId,"status",event.getStatus());}catch(ApiException ex){throw ex;}catch(Exception ex){throw new ApiException(400,"INVALID_WEBHOOK_PAYLOAD","Razorpay webhook payload could not be processed");}}
 @Transactional public BookingDtos.CancelView cancelBooking(String email,Long bookingId,String correlationId){UserAccount u=users.findByEmailIgnoreCase(email).orElseThrow(()->new ApiException(404,"USER_NOT_FOUND","User was not found"));Booking booking=bookingRepository.findByIdAndUserId(bookingId,u.getId()).orElseThrow(()->new ApiException(404,"BOOKING_NOT_FOUND","Booking was not found"));if(booking.getStatus()!=Booking.State.CONFIRMED)throw new ApiException(409,"INVALID_BOOKING_TRANSITION","Only confirmed bookings can be cancelled");if(!booking.getShowtime().getStartsAt().isAfter(Instant.now()))throw new ApiException(409,"CANCELLATION_CLOSED","This booking can no longer be cancelled");PaymentRecord p=payments.findByHoldIdAndProvider(booking.getHold().getId(),PaymentRecord.Provider.RAZORPAY).orElseThrow(()->new ApiException(404,"RAZORPAY_PAYMENT_NOT_FOUND","Gateway payment record was not found"));if(p.getProviderPaymentId()==null)throw new ApiException(409,"PAYMENT_REFERENCE_MISSING","Verified gateway payment reference is missing; operations reconciliation is required");RefundRecord refund=refunds.saveAndFlush(new RefundRecord(p,p.getAmount(),"REQUESTING","Customer booking cancellation"));booking.setStatus(Booking.State.REFUND_PENDING);p.setStatus(PaymentRecord.Status.REFUND_PENDING);try{JsonNode response=client().post().uri("/v1/payments/{id}/refund",p.getProviderPaymentId()).body(Map.of("amount",p.getAmount().movePointRight(2).longValueExact(),"notes",Map.of("cinebook_booking",booking.getBookingCode(),"reason","customer_cancellation"))).retrieve().body(JsonNode.class);if(response==null||!response.hasNonNull("id")){refund.setStatus("PENDING_RECONCILIATION");return new BookingDtos.CancelView(booking.getBookingCode(),booking.getStatus().name(),refund.getStatus(),"Refund request outcome is ambiguous. The booking remains pending refund; check the Razorpay test dashboard.");}refund.setProviderReference(response.path("id").asText());String state=response.path("status").asText("pending");if("processed".equalsIgnoreCase(state)||"completed".equalsIgnoreCase(state)){bookings.finalizeGatewayRefund(refund.getId());return new BookingDtos.CancelView(booking.getBookingCode(),Booking.State.REFUNDED.name(),"PROCESSED","Razorpay reported the test-mode refund as processed.");}refund.setStatus("REQUESTED");return new BookingDtos.CancelView(booking.getBookingCode(),booking.getStatus().name(),refund.getStatus(),"Refund request was accepted by Razorpay. The booking remains pending until the refund is confirmed.");}catch(RestClientResponseException ex){refund.setStatus(ex.getStatusCode().is4xxClientError()?"FAILED":"PENDING_RECONCILIATION");if(ex.getStatusCode().is4xxClientError()){booking.setStatus(Booking.State.CONFIRMED);p.setStatus(PaymentRecord.Status.SUCCEEDED);return new BookingDtos.CancelView(booking.getBookingCode(),booking.getStatus().name(),refund.getStatus(),"Razorpay rejected the refund request. Booking remains confirmed.");}return new BookingDtos.CancelView(booking.getBookingCode(),booking.getStatus().name(),refund.getStatus(),"Refund outcome is ambiguous. Check the Razorpay test dashboard before retrying.");}catch(Exception ex){refund.setStatus("PENDING_RECONCILIATION");return new BookingDtos.CancelView(booking.getBookingCode(),booking.getStatus().name(),refund.getStatus(),"Refund outcome is ambiguous. Check the Razorpay test dashboard before retrying.");}}
 private void requestRefundForCapturedPayment(Long paymentRecordId,String providerPaymentId,String correlationId){PaymentRecord p=payments.findById(paymentRecordId).orElseThrow();RefundRecord refund=refunds.findAllByPaymentIdOrderByCreatedAtDesc(p.getId()).stream().findFirst().orElseGet(()->refunds.saveAndFlush(new RefundRecord(p,p.getAmount(),"REQUESTING","Payment captured after seat hold became invalid")));if(refund.getProviderReference()!=null&&"PROCESSED".equals(refund.getStatus()))return;try{JsonNode response=client().post().uri("/v1/payments/{id}/refund",providerPaymentId).body(Map.of("amount",p.getAmount().movePointRight(2).longValueExact(),"notes",Map.of("cinebook_payment",p.getId().toString(),"reason","seat_hold_invalid"))).retrieve().body(JsonNode.class);if(response!=null&&response.hasNonNull("id")){refund.setProviderReference(response.path("id").asText());String state=response.path("status").asText("pending");if("processed".equalsIgnoreCase(state)||"completed".equalsIgnoreCase(state))bookings.finalizeGatewayRefund(refund.getId());else refund.setStatus("REQUESTED");}else refund.setStatus("PENDING_RECONCILIATION");}catch(Exception ex){refund.setStatus("PENDING_RECONCILIATION");}}
 private JsonNode eventEntity(JsonNode root,String event){if(event.startsWith("payment."))return root.path("payload").path("payment").path("entity");if(event.startsWith("refund."))return root.path("payload").path("refund").path("entity");return root.path("payload");}
 private RazorpayDtos.OrderView orderView(PaymentRecord p,String status,String message){return new RazorpayDtos.OrderView("RAZORPAY",keyId,p.getProviderReference(),p.getAmount().movePointRight(2).longValueExact(),p.getCurrency(),p.getId().toString(),status,message);}
 private RestClient client(){return restBuilder.clone().baseUrl("https://api.razorpay.com").defaultHeaders(h->h.setBasicAuth(keyId,keySecret)).build();}
 private boolean razorpayEnabled(){return "RAZORPAY".equalsIgnoreCase(mode)&&keyId!=null&&!keyId.isBlank()&&keySecret!=null&&!keySecret.isBlank();}
 private boolean checkoutSignatureValid(String orderId,String paymentId,String signature){return constantEquals(hmac(orderId+"|"+paymentId,keySecret),signature);}
 private static String shortReceipt(String raw){return "cb-"+sha256(raw).substring(0,30);}
 private static String hmac(String text,String secret){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal(text.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException("HMAC unavailable",e);}}
 private static String sha256(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private static boolean constantEquals(String expected,String actual){if(expected==null||actual==null)return false;return MessageDigest.isEqual(expected.getBytes(StandardCharsets.UTF_8),actual.trim().toLowerCase(Locale.ROOT).getBytes(StandardCharsets.UTF_8));}
}
